import{_ as a,H as t,f as o,i as r}from"./chunks/framework.DLd0CbzH.js";const p=JSON.parse('{"title":"Cash Flow (DDS)","description":"How actual cash movements are tracked, manual transactions, and tax payments are processed in OmniCraft ERP.","frontmatter":{"title":"Cash Flow (DDS)","description":"How actual cash movements are tracked, manual transactions, and tax payments are processed in OmniCraft ERP.","order":10},"headers":[],"relativePath":"docs/spaces/production/dds.md","filePath":"docs/spaces/production/dds.md"}'),s={name:"docs/spaces/production/dds.md"};function n(i,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation Under Development</p><p><strong>Dear Users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, with regular updates and expansions, the reference materials are also being updated gradually.</p><p>At this time, please treat the documentation as a guide—it is currently incomplete, may temporarily lack descriptions for certain features, or contain minor inaccuracies.</p></div><h1 id="💸-cash-flow-ledger-dds-cash-control" tabindex="-1">💸 Cash Flow Ledger (DDS): Cash Control <a class="header-anchor" href="#💸-cash-flow-ledger-dds-cash-control" aria-label="Permalink to &quot;💸 Cash Flow Ledger (DDS): Cash Control&quot;">​</a></h1><p>The <strong>&quot;Cash Flow&quot; (DDS)</strong> tab tracks physical cash. It logs every income and expense transaction strictly based on the actual movement of funds in your bank accounts or cash drawers.</p><p>The Cash Flow ledger reveals the movement of &quot;live&quot; cash, helping you prevent cash shortages and understand exactly what is spent on operational expenses.</p><hr><h2 id="📊-key-cash-metrics-three-cards" tabindex="-1">📊 Key Cash Metrics (Three Cards) <a class="header-anchor" href="#📊-key-cash-metrics-three-cards" aria-label="Permalink to &quot;📊 Key Cash Metrics (Three Cards)&quot;">​</a></h2><p>Three key metrics representing your cash balance are displayed at the top of the screen:</p><ol><li><strong>Actual Inflow (Cash):</strong> The total amount of all funds that physically entered your business (sales revenue, bespoke order down payments, masterclass tuition).</li><li><strong>Actual Outflow (Expenses):</strong> All funds that left the workshop (materials procurement, advertising, logistics, rent, taxes).</li><li><strong>Net Balance (Saldo):</strong> The difference between Inflow and Outflow at the current moment.</li></ol><div class="tip custom-block"><p class="custom-block-title">Why a Negative Balance is Normal</p><p>While a negative cash balance is considered a grave error in traditional accounting, within the OmniCraft ERP philosophy (under the <em>mixed finances</em> approach), <strong>a negative Cash Flow balance is a normal operating indicator</strong>.</p><p>It simply indicates that at the start or during operations, you invested a certain amount of personal funds (e.g., purchased a laser engraver or paid for a large leather roll with your personal card). The program accurately records this personal investment. As soon as the Cash Flow balance crosses into a positive value, it signals that the business has fully returned your initial investments and has started generating net cash profit.</p></div><hr><h2 id="➕-recording-other-manual-transactions" tabindex="-1">➕ Recording Other (Manual) Transactions <a class="header-anchor" href="#➕-recording-other-manual-transactions" aria-label="Permalink to &quot;➕ Recording Other (Manual) Transactions&quot;">​</a></h2><p>Not all financial flows in a business are directly tied to standard product sales or raw material purchases. To record miscellaneous revenues and expenses, use the <strong>&quot;Record Other Transactions&quot;</strong> form.</p><h3 id="_1-select-the-transaction-type" tabindex="-1">1. Select the transaction type: <a class="header-anchor" href="#_1-select-the-transaction-type" aria-label="Permalink to &quot;1. Select the transaction type:&quot;">​</a></h3><ul><li><strong>Expense (Outflow):</strong> Indirect operating costs of your workshop.</li><li><strong>Non-Operating Income (Inflow):</strong> Funds earned through business activities but unrelated to selling finished products from the showroom.</li></ul><h3 id="_2-specify-the-category" tabindex="-1">2. Specify the category: <a class="header-anchor" href="#_2-specify-the-category" aria-label="Permalink to &quot;2. Specify the category:&quot;">​</a></h3><p>For precise analytics, select one of the system categories:</p><ul><li><em>For Expenses:</em> <strong>Advertising</strong> (ads, promos), <strong>Hosting &amp; Software</strong> (subscriptions, domains, web platforms), <strong>Rent</strong>, or a generic <strong>Other</strong> category.</li><li><em>For Inflows:</em> <strong>Masterclass</strong> (if you conduct offline or online classes), <strong>Bespoke Services</strong> (custom commission work, product repairs), or a generic <strong>Other</strong> category.</li></ul><h3 id="_3-amount-and-comment" tabindex="-1">3. Amount and Comment: <a class="header-anchor" href="#_3-amount-and-comment" aria-label="Permalink to &quot;3. Amount and Comment:&quot;">​</a></h3><ul><li><strong>Smart Input Field:</strong> Upon clicking the amount field, placeholder zeros are cleared automatically so you do not waste time erasing characters.</li><li><strong>Comment:</strong> Briefly describe the operation (e.g., <em>“Ad placement with craft blogger”</em> or <em>“Down payment for bespoke leather jacket”</em>).</li></ul><h3 id="_4-transaction-date" tabindex="-1">4. Transaction Date: <a class="header-anchor" href="#_4-transaction-date" aria-label="Permalink to &quot;4. Transaction Date:&quot;">​</a></h3><p>Using the calendar icon, you can backdate transactions to any past date, allowing you to restore an accurate historical log.</p><hr><h2 id="🧾-dedicated-block-tax-payments" tabindex="-1">🧾 Dedicated Block: Tax Payments <a class="header-anchor" href="#🧾-dedicated-block-tax-payments" aria-label="Permalink to &quot;🧾 Dedicated Block: Tax Payments&quot;">​</a></h2><p>To simplify fiscal tracking, a quick <strong>&quot;Pay Tax&quot;</strong> form is provided.</p><ol><li>Enter the calculated and paid tax amount.</li><li>The program will automatically deduct this amount on the selected date, assign it the <strong>&quot;Taxes&quot;</strong> category, and add a corresponding entry to your history.</li></ol><hr><h2 id="📖-cash-flow-log-cash-registry" tabindex="-1">📖 Cash Flow Log (Cash Registry) <a class="header-anchor" href="#📖-cash-flow-log-cash-registry" aria-label="Permalink to &quot;📖 Cash Flow Log (Cash Registry)&quot;">​</a></h2><p>A detailed transaction log is located on the left side of the screen.</p><ul><li>Inflows are highlighted in bright green with a <strong>&quot;+&quot;</strong> sign; outflows are highlighted in red with a <strong>&quot;-&quot;</strong> sign.</li><li>Entries are sorted chronologically from newest to oldest.</li><li>The table supports pagination (paged viewing of 20 records) to ensure smooth, lag-free performance even with extensive logs.</li></ul>',29)])])}const g=a(s,[["render",n]]);export{p as __pageData,g as default};
